settings._cssCustom:
.cta-card-sierra {
  border: var(--border);
}

/* Desktop Styles
Change min-width value to suitable stacking point based
on your particular image.
*/
@media (min-width: 1235px) {
  .cta-card-sierra.cta-card-sierra {
    --card-padding: var(--space-xxl);
    --text-width: 36ch;
    --content-gap: var(--space-l);
    --overlap: calc(var(--section-space-m) / 1.5);
  	display: flex;
    flex-direction: row;
  }
  .cta-card-sierra__media.cta-card-sierra__media {
  	position: absolute;
    inset-block-end: 0;
    inset-inline-end: calc(var(--card-padding) / 2);
    inline-size: calc(100% - var(--content-gap) - (var(--text-width) + var(--card-padding) * 2));
    max-block-size: calc(100% + var(--overlap));
  }
  .cta-card-sierra__content-wrapper.cta-card-sierra__content-wrapper {
    margin-bottom: 0;
   }
}

/* Mobile */
.cta-card-sierra {
	--card-padding: var(--space-l);
	--text-width: 100%;
}

.fr-icon-link-alpha {
  --link-color: var(--black);
  --link-color-hover: var(--primary);
	--icon-size: 1em;
  --icon-color: var(--black);
  --icon-color-hover: var(--black);
  --icon-gap: .25em;
  --icon-translate-distance: .25em;
  --icon-transition-duration: 300ms;
  --icon-transition-function: ease-in-out;

  /* Prevent Line Breaks */
  white-space: nowrap;
}

/* Link */
.fr-icon-link-alpha {
	color: var(--link-color);
  text-decoration: underline;
  text-underline-offset: var(--link-underline-offset, .25em);
}

.fr-icon-link-alpha:hover {
	color: var(--link-color-hover);
}

/* Icon */
.fr-icon-link-alpha .icon {
	transition: translate var(--icon-transition-duration) var(--icon-transition-function);
	fill: var(--icon-color);
}

.fr-icon-link-alpha:hover .icon {
	translate: var(--icon-translate-distance) 0;
  fill: var(--icon-color-hover);
}

/* Light Version */
.fr-icon-link-alpha--light {
  --link-color: var(--white);
  --link-color-hover: var(--primary);
	--icon-size: 1em;
  --icon-color: var(--white);
  --icon-color-hover: var(--primary);
}
